  in_demo              BOOLEAN   COMMENT 'Part of the six-step headline demonstration.',
  CONSTRAINT pk_use_cases PRIMARY KEY (domain, ontology_version, use_case)
) COMMENT 'The client-facing catalogue, each row bound to the mechanism that answers it. A use case naming a decision this catalogue does not contain fails the build -- which is what stops a capability being promised that the platform does not have. `status` is deliberately honest: buildable, needs_instances, or blocked with the Claris question named.';

CREATE OR REPLACE TABLE claris.retail_ontology.projection_matrix (
  domain                         STRING    COMMENT 'Which domain\'s model this row belongs to.',
  ontology_version               STRING    COMMENT 'Which version of that model.',
  rule                           STRING    COMMENT 'Identifier.',
  ordinal                        INT       COMMENT 'Declaration order.',
  identity_effect                STRING    COMMENT 'What IDENTITY_ASSESSMENT concluded.',
  target_system                  STRING    COMMENT 'all_skus | sap | ww_pricing | salesforce.',
  target_object_type             STRING    COMMENT 'What that system calls the record.',
  proposed_action                STRING    COMMENT 'CREATE | UPDATE | RETIRE | NO_ACTION.',
  requires_new_target_identity   BOOLEAN   COMMENT 'Whether a new physical key is minted.',
  projection_reason              STRING    COMMENT 'WHY. NULL only where the action is NO_ACTION.',
  counts_as_proliferation        BOOLEAN   COMMENT 'Whether this record is a cost of the source system rather than catalogue growth.',
  owner                          STRING    COMMENT 'The Claris role that must confirm this row.',
  status                         STRING    COMMENT 'proposed | confirm_with_claris | confirmed.',
  rationale                      STRING    COMMENT 'The reasoning, so the row can be argued with.',
  CONSTRAINT pk_projection_matrix PRIMARY KEY (domain, ontology_version, rule)
) COMMENT 'What each target system requires, GIVEN what the identity decision concluded. This is the table UC-19 predicts from and UC-09 explains from, and it is the one that makes the argument: the same physical record is legitimate growth under CREATE_CONFIGURATION and a source-system cost under NEW_VERSION. Claris has no way to tell those apart today.';

CREATE OR REPLACE TABLE claris.retail_ontology.change_impact (
  domain                  STRING    COMMENT 'Which domain\'s model this row belongs to.',
  ontology_version        STRING    COMMENT 'Which version of that model.',
  change_type             STRING    COMMENT 'The governed change type.',
  ordinal                 INT       COMMENT 'Declaration order.',
  identity_rule           STRING    COMMENT 'The rule that decides the effect.',
  reads_dimension         STRING    COMMENT 'The dimension the rule turns on.',
  proposed_effect         STRING    COMMENT 'The identity outcome that follows.',
  affects_product         BOOLEAN   COMMENT 'Creates or changes a Product.',
  affects_configuration   BOOLEAN   COMMENT 'Creates a new canonical identity.',
  affects_version         BOOLEAN   COMMENT 'Creates a new version.',
  affects_pricing         BOOLEAN   COMMENT 'Changes what a customer pays.',
  affects_entitlement     BOOLEAN   COMMENT 'Changes what a customer may do.',
  affects_hierarchy       BOOLEAN   COMMENT 'Changes classification.',
  systems_affected        STRING    COMMENT 'Target systems that must act.',
  records_created         INT       COMMENT 'Physical identities minted across all targets.',
  proliferation_records   INT       COMMENT 'Of those, how many exist only because of a source-system constraint.',
  observed_materials      INT       COMMENT 'Materials this change type actually produced in the measured corpus.',
  identity_decidable      BOOLEAN   COMMENT 'False where the governing dimension is still UNKNOWN.',
  blocked_by_dimension    STRING    COMMENT 'Which dimension blocks it, where one does.',
  CONSTRAINT pk_change_impact PRIMARY KEY (domain, ontology_version, change_type)
) COMMENT 'UC-17, derived rather than authored. Given a change type, what it touches and what it will cost -- computed from the identity rules, the dimension catalogue and the projection matrix, so there is no third place for the same claim to drift. `identity_decidable` is false wherever the dimension the rule reads is still ungoverned, which is most of them.';

CREATE OR REPLACE TABLE claris.retail_ontology.ontology_notes (
  domain             STRING   COMMENT 'Which domain\'s model this row belongs to.',
  ontology_version   STRING   COMMENT 'Which version of that model.',
  note_id            STRING   COMMENT 'Identifier.',
  ordinal            INT      COMMENT 'Declaration order.',
  subject            STRING   COMMENT 'What the question is about.',
  question           STRING   COMMENT 'The question, as it should be asked.',
  blocks             STRING   COMMENT 'What cannot proceed without an answer.',
  owner              STRING   COMMENT 'Who owes it.',
  status             STRING   COMMENT 'open | answered.',
  CONSTRAINT pk_ontology_notes PRIMARY KEY (domain, ontology_version, note_id)
) COMMENT 'What the model does not yet know, and who owes the answer. Held as rows rather than prose so \'awaiting Claris\' is a query, and so a note cannot be quietly dropped when a document is rewritten.';

-- ---------------------------------------------------------------------------
-- Everything awaiting a named person at Claris, as a query rather than a slide.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE VIEW claris.retail_ontology.open_decisions
COMMENT 'Every governed row still unconfirmed, with its owner and what is at stake. Ordered so the expensive questions surface first.'
AS
SELECT
  'dimension'                                  AS item_type,
  dimension                                    AS item,
  label                                        AS subject,
  authority                                    AS owed_by,
  governance_state                             AS state,
  COALESCE(impact_if_wrong, '-')               AS at_stake,
  CASE WHEN blocks_identity_assessment
       THEN 'Blocks IDENTITY_ASSESSMENT for any change touching this dimension'
       ELSE '-' END                            AS consequence,
  rationale
FROM claris.retail_ontology.configuration_dimensions
WHERE blocks_identity_assessment

UNION ALL

SELECT
  'identity_rule',
  rule,
  change_type,
  owner,
  status,
  CONCAT(CAST(observed_materials AS STRING), ' materials observed'),
  CONCAT('Proposes ', proposed_effect),
  rationale
FROM claris.retail_ontology.identity_rules
WHERE status <> 'confirmed'

UNION ALL

SELECT
  'projection_rule',
  rule,
  CONCAT(source_object, ' to ', target_system),
  owner,
  status,
  CASE WHEN requires_new_target_identity
       THEN 'Mints a new physical identity' ELSE 'Updates in place' END,
  CONCAT('Proposes ', proposed_action),
  rationale
FROM claris.retail_ontology.projection_rules
WHERE status <> 'confirmed'

UNION ALL

SELECT
  'open_question',
  note_id,
  subject,
  owner,
  'open',
  '-',
  blocks,
  question
FROM claris.retail_ontology.ontology_notes;

-- ---------------------------------------------------------------------------
-- UC-10 / UC-22. Business-required growth versus legacy-imposed proliferation,
-- computed from the identity rules and the projection matrix rather than
-- asserted. Ordered so the expensive change types surface first.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE VIEW claris.retail_ontology.proliferation_forecast
COMMENT 'Per change type: what the ontology decides, what the legacy systems project, and how much of the resulting catalogue growth is a source-system cost rather than a business decision.'
AS
SELECT
  ci.change_type,
  ci.proposed_effect                              AS ontology_decides,
  ci.observed_materials                           AS materials_in_corpus,
  ci.records_created                              AS physical_records_per_change,
  ci.proliferation_records                        AS legacy_driven_per_change,
  CASE WHEN ci.records_created = 0 THEN 0
       ELSE ROUND(100.0 * ci.proliferation_records / ci.records_created, 1)
  END                                             AS pct_legacy_driven,
  CASE WHEN ci.proliferation_records > 0
       THEN ci.observed_materials ELSE 0 END      AS materials_attributable_to_legacy,
  ci.identity_decidable,
  ci.blocked_by_dimension,
  ci.systems_affected
FROM claris.retail_ontology.change_impact ci
ORDER BY materials_attributable_to_legacy DESC, ci.observed_materials DESC;
