INSERT INTO claris.retail_ontology.ontology_release (domain, ontology_version, description, status, source_sha256) VALUES
  ('retail', '2026.10', 'The Claris retail product model. Eleven object types, seventeen links, twenty-one verbs, twenty evidence types and five decisions. v0.4 separates stable Configuration identity from ConfigurationVersion state from Projection into legacy systems, which is what lets one canonical version and seventy-eight physical rows both be true -- and lets the second be counted as a cost of the source systems rather than as catalogue growth.', 'draft', 'bf7a2f7f9e1d950f');
INSERT INTO claris.retail_ontology.object_types (domain, ontology_version, object_type, display_name, ordinal, grain, primary_key, kind, semantic_definition, why_it_exists) VALUES
  ('retail', '2026.10', 'product', 'Product', 0, 'entity', 'product_id', 'business', 'Stable commercial product identity', 'Separates what Claris sells from how many rows represent it'),
  ('retail', '2026.10', 'configuration', 'Configuration', 1, 'entity', 'configuration_id', 'business', 'A stable sellable identity. Never re-minted once created.', 'The anchor. If this changes when a tier band moves, the whole proliferation argument collapses -- so it holds only the dimension tuple Claris confirms as identity-bearing, and nothing else.'),
  ('retail', '2026.10', 'configuration_version', 'ConfigurationVersion', 2, 'entity', 'version_id', 'business', 'The changing business state of one configuration', 'Every mutation lands here instead of minting a sibling. This is the subject of readiness, the parent of projections, and the numerator of the proliferation ratio.'),
  ('retail', '2026.10', 'configuration_dimension', 'ConfigurationDimension', 3, 'entity', 'dimension_id', 'business', 'An attribute a configuration can carry, and its governance', 'Modelled as an object rather than a column so identity semantics stay policy, not schema. user_tier can sit at UNKNOWN today and become TRUE or FALSE after governance, with no redesign.'),
  ('retail', '2026.10', 'configuration_value', 'ConfigurationValue', 4, 'entity', 'value_id', 'business', 'One dimension set to one value on one version, for a period', 'Makes \'which versions turn on user_tier\' a traversal rather than a column scan, and lets a value carry the evidence that set it.'),
  ('retail', '2026.10', 'projection', 'Projection', 5, 'system', 'projection_id', 'system', 'A representation of a version inside a target system', 'A material number is not a business object; it is what a legacy system needs in order to hold a version. Recording it here is what turns \'78 rows were created\' into \'78 rows were created BECAUSE of a source-system constraint\'.'),
  ('retail', '2026.10', 'actor', 'Actor', 6, 'entity', 'actor_id', 'business', 'A department, a named person, or a machine that asserts or acts', 'Promoted from a lookup because ownership is the workbench\'s core promise. As a lookup it could only be joined; as an object type it can be traversed, and separation of duties becomes checkable.'),
  ('retail', '2026.10', 'launch', 'Launch', 7, 'entity', 'launch_id', 'business', 'The effort to make one or more configurations sellable', 'Coordination spine; the thing a person actually tracks'),
  ('retail', '2026.10', 'evidence', 'Evidence', 8, 'event', 'evidence_id', 'business', 'A sourced statement from a system or a person', 'Preserves provenance and lets systems disagree without one silently winning'),
  ('retail', '2026.10', 'decision', 'Decision', 9, 'system', 'decision_id', 'system', 'A conclusion reached against declared inputs', 'The audit object the workbench renders; nothing is computed in the UI'),
  ('retail', '2026.10', 'action', 'Action', 10, 'system', 'action_id', 'system', 'Something done to the world, and what entitled it', 'Without it, verbs are untraceable and entitlement is unenforceable');
