INSERT INTO claris.retail_ontology.links (domain, ontology_version, link, ordinal, source_type, target_type, cardinality, inverse, semantic_definition, enforces) VALUES
  ('retail', '2026.10', 'has_configuration', 0, 'product', 'configuration', '1..n', 'belongs_to', 'A configuration is a governed variation of exactly one product', 'Adding a geo or a term must not create a second Product'),
  ('retail', '2026.10', 'has_version', 1, 'configuration', 'configuration_version', '1..n', 'version_of', 'A configuration accumulates versions; its identity does not change', 'THE central rule. A tier restructure adds version 3, it does not add configuration #2.'),
  ('retail', '2026.10', 'previous_version', 2, 'configuration_version', 'configuration_version', '0..1', 'next_version', 'The version this one succeeded', 'Replaces v0.3\'s `supersedes`, which described replacement of one identity by another -- the very behaviour we are removing'),
  ('retail', '2026.10', 'has_dimension_value', 3, 'configuration_version', 'configuration_value', '0..n', 'on_version', 'The dimension settings this version carries', 'Dimensions are data, not columns, so their identity semantics can change without a schema migration'),
  ('retail', '2026.10', 'defined_by', 4, 'configuration_value', 'configuration_dimension', 'n..1', 'values', 'The governed dimension this value belongs to', 'A value cannot exist for a dimension nobody governs'),
  ('retail', '2026.10', 'projected_as', 5, 'configuration_version', 'projection', '0..n', 'projects', 'The physical rows target systems required for this version', 'One canonical version to many legacy identities -- and the ratio is the proliferation measurement'),
  ('retail', '2026.10', 'created_by', 6, 'configuration_version', 'decision', '0..1', 'created_versions', 'The identity decision that minted this version', 'No version appears without a conclusion behind it'),
  ('retail', '2026.10', 'launches', 7, 'launch', 'configuration_version', '1..n', 'launched_by', 'A launch attempts to make these versions sellable', 'One launch can carry 54 versions; readiness is per version'),
  ('retail', '2026.10', 'about', 8, 'evidence', 'product|configuration|configuration_version|launch', 'n..1', 'has_evidence', 'The business object this statement is about', 'Evidence is never free-floating; it always has a subject'),
  ('retail', '2026.10', 'asserted_by', 9, 'evidence', 'actor', 'n..1', 'asserted', 'Who or what made this statement', 'Two actors can assert contradictory facts and both are kept'),
  ('retail', '2026.10', 'concluded_about', 10, 'decision', 'configuration_version|launch', 'n..1', 'decisions', 'The object the conclusion is about', 'A decision is scoped; it cannot silently apply to a sibling'),
  ('retail', '2026.10', 'supported_by', 11, 'decision', 'evidence', '1..n', 'supports', 'The evidence the conclusion rested on, at the version it was read', 'Replay: the same evidence must reproduce the same outcome'),
  ('retail', '2026.10', 'authorized_by', 12, 'action', 'decision', 'n..1', 'authorizes', 'The specific conclusion that entitled this action', 'A role alone never authorizes a consequential action'),
  ('retail', '2026.10', 'performed_by', 13, 'action', 'actor', 'n..1', 'performed', 'Who did it', 'Separation of duties is checkable rather than assumed'),
  ('retail', '2026.10', 'produces', 14, 'action', 'evidence', '0..n', 'produced_by', 'The statement this action created', 'Closes the loop: evidence has an action behind it, not just a source row'),
  ('retail', '2026.10', 'creates_projection', 15, 'action', 'projection', '0..n', 'created_by_action', 'The target-system row this action wrote', 'A legacy row is attributable to an action and a reason, never \'the system just does that\''),
  ('retail', '2026.10', 'member_of', 16, 'actor', 'actor', '0..1', 'members', 'A person belongs to a department; a joint body has constituents', 'Lets Ops + IS&T stop being a fictional seventh department and become two actors on one action');
