INSERT INTO claris.retail_ontology.inference_rules (domain, ontology_version, rule, ordinal, concludes_evidence, from_evidence, rationale, confidence) VALUES
  ('retail', '2026.10', 'INF-001', 0, 'technical_approved', 'zupdm_approved', 'ZUPDM approval flag set in SAP (S13) only occurs after Technical readiness approved (S12), so its presence proves it.', 'Establishes that it happened; not when, and not by whom.'),
  ('retail', '2026.10', 'INF-002', 1, 'price_approved', 'fully_approved', 'Fully approved in all_skus (S17) only occurs after Pricing approved (S16), so its presence proves it.', 'Establishes that it happened; not when, and not by whom.');
INSERT INTO claris.retail_ontology.contradiction_checks (domain, ontology_version, check_id, ordinal, left_evidence, right_evidence, semantic_definition, catches) VALUES
  ('retail', '2026.10', 'CC-001', 0, 'fully_approved', 'conditions_in_sap', 'all_skus says fully approved but SAP holds no condition records', 'Priced, signed off, and unsellable -- the state that held one launch for 196 days with every participant believing their part was done'),
  ('retail', '2026.10', 'CC-002', 1, 'price_rows_loaded', 'conditions_in_sap', 'ww_pricing and SAP disagree about the price', 'Silent drift after a re-price; nothing compares them'),
  ('retail', '2026.10', 'CC-003', 2, 'material_active', 'published', 'all_skus says active but Salesforce has no catalogue entry', 'Active but invisible to Sales'),
  ('retail', '2026.10', 'CC-004', 3, 'hierarchy_in_con', 'hierarchy_in_prd', 'Loaded to SAP CON but never to PRD', 'A launch that stops between the two loads leaves no other trace');
