INSERT INTO claris.retail_ontology.decision_outputs (domain, ontology_version, decision, outcome, ordinal, semantic_definition, entitles_actions) VALUES
  ('retail', '2026.10', 'LAUNCH_READINESS', 'READY', 0, 'All required evidence present and uncontradicted', 'ACTIVATE_MATERIAL, PUBLISH_TO_SALESFORCE'),
  ('retail', '2026.10', 'LAUNCH_READINESS', 'BLOCKED', 1, 'Two sources disagree, or an owner has explicitly refused. Somebody must reconcile or overturn something before this moves.', NULL),
  ('retail', '2026.10', 'LAUNCH_READINESS', 'AWAITING_APPROVAL', 2, 'A person owes a judgment and has not given one. Not refused -- untouched. This is where launches sit for 296 days.', NULL),
  ('retail', '2026.10', 'LAUNCH_READINESS', 'AWAITING_EVIDENCE', 3, 'A system has not yet reported a fact the platform expects. Nobody is being asked for anything; something has not propagated.', NULL),
  ('retail', '2026.10', 'LAUNCH_READINESS', 'CANNOT_DECIDE', 4, 'The platform cannot even determine what is missing, because an upstream decision has not concluded.', NULL),
  ('retail', '2026.10', 'COMMERCIAL_INTENT', 'APPROVED', 0, 'Claris intends to sell this', 'SUBMIT_INTENT'),
  ('retail', '2026.10', 'COMMERCIAL_INTENT', 'DEFERRED', 1, 'Wanted, but not now. The launch does not start.', NULL),
  ('retail', '2026.10', 'COMMERCIAL_INTENT', 'REJECTED', 2, 'Not wanted', NULL),
  ('retail', '2026.10', 'LAUNCH_VIABILITY', 'CONTINUE', 0, 'Still wanted; the blockage is worth clearing', NULL),
  ('retail', '2026.10', 'LAUNCH_VIABILITY', 'ABANDON', 1, 'No longer worth finishing. Stops the launch and releases what it holds.', 'ABANDON_LAUNCH'),
  ('retail', '2026.10', 'LAUNCH_VIABILITY', 'NOT_ASKED', 2, 'Nobody has been asked. The default, and the state every stalled launch in the corpus is in.', NULL),
  ('retail', '2026.10', 'CHANGE_CLASSIFICATION', 'offering_launch', 0, 'A product family Claris does not sell today', NULL),
  ('retail', '2026.10', 'CHANGE_CLASSIFICATION', 'geo_add', 1, 'An existing offering into a new market', NULL),
  ('retail', '2026.10', 'CHANGE_CLASSIFICATION', 'term_add', 2, 'A new commitment length on an existing offering', NULL),
  ('retail', '2026.10', 'CHANGE_CLASSIFICATION', 'segment_add', 3, 'A new customer segment on an existing offering', NULL),
  ('retail', '2026.10', 'CHANGE_CLASSIFICATION', 'tier_restructure', 4, 'The user-tier bands change', NULL),
  ('retail', '2026.10', 'CHANGE_CLASSIFICATION', 'repackage', 5, 'The fulfilment or packaging form changes', NULL),
  ('retail', '2026.10', 'CHANGE_CLASSIFICATION', 'reclassify', 6, 'The hierarchy position changes; nothing sellable changes', NULL),
  ('retail', '2026.10', 'CHANGE_CLASSIFICATION', 'price_change', 7, 'Price only', NULL),
  ('retail', '2026.10', 'CHANGE_CLASSIFICATION', 'rename', 8, 'Descriptive metadata only', NULL),
  ('retail', '2026.10', 'CHANGE_CLASSIFICATION', 'CANNOT_DECIDE', 9, 'The request does not say enough to classify', NULL),
  ('retail', '2026.10', 'IDENTITY_ASSESSMENT', 'CREATE_PRODUCT', 0, 'New product family or business concept', 'CREATE_PRODUCT'),
  ('retail', '2026.10', 'IDENTITY_ASSESSMENT', 'CREATE_CONFIGURATION', 1, 'New sellable identity under an existing product', 'CREATE_CONFIGURATION'),
  ('retail', '2026.10', 'IDENTITY_ASSESSMENT', 'USE_EXISTING', 2, 'The requested sellable configuration already exists. The platform returns its identity instead of creating a second one.', NULL),
