INSERT INTO claris.retail_ontology.enum_values (domain, ontology_version, enum_name, value, ordinal, semantic_definition) VALUES
  ('retail', '2026.10', 'evidence_state', 'present', 0, 'The fact is established.'),
  ('retail', '2026.10', 'evidence_state', 'absent', 1, 'Nothing asserts it. Forces CANNOT_DECIDE where required.'),
  ('retail', '2026.10', 'evidence_state', 'rejected', 2, 'An owner actively refused, with a reason. Not the same as absent, and the difference is what separates a decision nobody made from one somebody declined to make.'),
  ('retail', '2026.10', 'evidence_state', 'contradicted', 3, 'Two sources disagree. Neither is discarded.'),
  ('retail', '2026.10', 'provenance', 'observed', 0, 'Read from the system that holds the fact.'),
  ('retail', '2026.10', 'provenance', 'inferred', 1, 'Deduced from a downstream artifact.'),
  ('retail', '2026.10', 'provenance', 'asserted', 2, 'A person told the workbench.'),
  ('retail', '2026.10', 'readiness_outcome', 'READY', 0, 'All required evidence present and uncontradicted.'),
  ('retail', '2026.10', 'readiness_outcome', 'BLOCKED', 1, 'Two sources disagree, or an owner explicitly refused. Somebody must reconcile or overturn something.'),
  ('retail', '2026.10', 'readiness_outcome', 'AWAITING_APPROVAL', 2, 'A person owes a judgment and has not given one. Not refused -- untouched. This is where launches sit for 296 days.'),
  ('retail', '2026.10', 'readiness_outcome', 'AWAITING_EVIDENCE', 3, 'A system has not reported a fact yet. Nobody is being asked for anything.'),
  ('retail', '2026.10', 'readiness_outcome', 'CANNOT_DECIDE', 4, 'An upstream decision has not concluded, so the platform cannot even say what is missing.'),
  ('retail', '2026.10', 'identity_effect', 'CREATE_PRODUCT', 0, 'New product family or business concept.'),
  ('retail', '2026.10', 'identity_effect', 'CREATE_CONFIGURATION', 1, 'New sellable identity under an existing product.'),
  ('retail', '2026.10', 'identity_effect', 'USE_EXISTING', 2, 'The requested configuration already exists. The platform returns its identity rather than creating a second one.'),
  ('retail', '2026.10', 'identity_effect', 'NEW_VERSION', 3, 'Existing identity, changed business state. No new configuration; any target row that follows is a projection cost, not catalogue growth.'),
  ('retail', '2026.10', 'identity_effect', 'NO_BUSINESS_CHANGE', 4, 'No canonical mutation.'),
  ('retail', '2026.10', 'identity_effect', 'CANNOT_DECIDE', 5, 'Required evidence or governing policy is missing.'),
  ('retail', '2026.10', 'identity_governance', 'TRUE', 0, 'Confirmed identity-bearing by a named authority.'),
  ('retail', '2026.10', 'identity_governance', 'FALSE', 1, 'Confirmed not identity-bearing by a named authority.'),
  ('retail', '2026.10', 'identity_governance', 'UNKNOWN', 2, 'Nobody has signed. Any change touching this dimension concludes CANNOT_DECIDE / IDENTITY_POLICY_NOT_DEFINED rather than being guessed from a sibling dimension.'),
  ('retail', '2026.10', 'configuration_status', 'proposed', 0, 'We have proposed an answer and shown our reasoning.'),
  ('retail', '2026.10', 'configuration_status', 'confirmed', 1, 'A named person at Claris has signed it.'),
  ('retail', '2026.10', 'configuration_status', 'disputed', 2, 'Claris disagreed; the row needs rework.'),
  ('retail', '2026.10', 'configuration_status', 'undefined', 3, 'No proposal is possible yet.'),
  ('retail', '2026.10', 'use_case_status', 'buildable', 0, 'Nothing external is required. It can be built now.'),
  ('retail', '2026.10', 'use_case_status', 'needs_instances', 1, 'The decision logic exists; the runtime tables that hold concluded decisions do not yet.'),
  ('retail', '2026.10', 'use_case_status', 'blocked', 2, 'Awaiting a named answer from Claris. The blocker is on the row.'),
  ('retail', '2026.10', 'risk', 'low', 0, 'Reversible, no downstream consequence.'),
  ('retail', '2026.10', 'risk', 'elevated', 1, 'Writes to a system of record.'),
  ('retail', '2026.10', 'risk', 'consequential', 2, 'Changes what a customer can buy.'),
  ('retail', '2026.10', 'projection_action', 'CREATE', 0, 'A new physical record in the target system'),
  ('retail', '2026.10', 'projection_action', 'UPDATE', 1, 'An existing target record amended in place'),
  ('retail', '2026.10', 'projection_action', 'RETIRE', 2, 'An existing target record closed or deactivated'),
  ('retail', '2026.10', 'projection_action', 'NO_ACTION', 3, 'The target system needs nothing for this version'),
  ('retail', '2026.10', 'projection_reason', 'BUSINESS_IDENTITY_REQUIRED', 0, 'A genuinely new product or sellable identity'),
  ('retail', '2026.10', 'projection_reason', 'CONFIGURATION_REQUIRED', 1, 'A new governed configuration under an existing product'),
  ('retail', '2026.10', 'projection_reason', 'LEGACY_SYSTEM_CONSTRAINT', 2, 'The canonical model needed no new identity, but the target system cannot version in place'),
  ('retail', '2026.10', 'projection_reason', 'TARGET_SYSTEM_REQUIREMENT', 3, 'The target system\'s own model demands a distinct record (SAP material master immutability, for example)'),
  ('retail', '2026.10', 'projection_reason', 'CORRECTION', 4, 'Repairing an earlier bad projection'),
  ('retail', '2026.10', 'projection_reason', 'OTHER', 5, 'Unclassified. Every row here is a gap in the taxonomy.'),
  ('retail', '2026.10', 'projection_status', 'REQUIRED', 0, 'Determined necessary, not yet written'),
  ('retail', '2026.10', 'projection_status', 'PENDING', 1, 'Submitted to the target system'),
  ('retail', '2026.10', 'projection_status', 'CONFIRMED', 2, 'Observed present in the target system'),
  ('retail', '2026.10', 'projection_status', 'FAILED', 3, 'The target system rejected it'),
  ('retail', '2026.10', 'projection_status', 'SUPERSEDED', 4, 'Replaced by a later projection'),
  ('retail', '2026.10', 'decision_reason_code', 'IDENTITY_POLICY_NOT_DEFINED', 0, 'No confirmed identity rule exists for a dimension this change touches. The platform declines rather than guessing.'),
  ('retail', '2026.10', 'decision_reason_code', 'EVIDENCE_ABSENT', 1, 'A required statement has never been made by anyone'),
  ('retail', '2026.10', 'decision_reason_code', 'EVIDENCE_CONTRADICTED', 2, 'Two sources disagree and neither has been reconciled'),
  ('retail', '2026.10', 'decision_reason_code', 'EVIDENCE_REJECTED', 3, 'An owner explicitly refused, with a reason'),
  ('retail', '2026.10', 'decision_reason_code', 'DEPENDENCY_UNRESOLVED', 4, 'An upstream decision has not concluded'),
  ('retail', '2026.10', 'decision_reason_code', 'REQUEST_UNDERSPECIFIED', 5, 'The change request does not say enough to classify');
INSERT INTO claris.retail_ontology.configuration_dimensions (domain, ontology_version, dimension, ordinal, label, data_type, identity_affecting, governance_state, blocks_identity_assessment, proposed_identity_affecting, pricing_affecting, entitlement_affecting, hierarchy_affecting, rationale, impact_if_wrong, authority, owner, status, effective_from, effective_to, confirmed_by, confirmed_on) VALUES
  ('retail', '2026.10', 'geo', 0, 'Region', 'string', 'UNKNOWN', 'PROPOSED', TRUE, TRUE, TRUE, TRUE, NULL, '63 materials in the corpus came from geo additions and none replaced an existing material -- the business already treats a region as a new sellable thing. Each region also carries its own currency and price list.', NULL, 'Product Management', 'Product Management', 'proposed', '2020-01-01', NULL, NULL, NULL),
  ('retail', '2026.10', 'term', 1, 'Term', 'string', 'UNKNOWN', 'PROPOSED', TRUE, TRUE, TRUE, TRUE, NULL, '33 materials, none replacing an existing one. Annual and monthly are different commitments with different revenue recognition, not two prices for the same thing.', NULL, 'Product Management', 'Product Management', 'proposed', '2020-01-01', NULL, NULL, NULL),
  ('retail', '2026.10', 'segment', 2, 'Segment', 'string', 'UNKNOWN', 'PROPOSED', TRUE, TRUE, TRUE, TRUE, NULL, '19 materials, none replacing an existing one. Retail, education and partner carry different entitlement and eligibility, not only a different price.', NULL, 'Product Management + Finance', 'Product Management + Finance', 'proposed', '2020-01-01', NULL, NULL, NULL),
  ('retail', '2026.10', 'user_tier', 3, 'User tier', 'range_band', 'UNKNOWN', 'PROPOSED', TRUE, FALSE, TRUE, TRUE, FALSE, 'THE EXPENSIVE ONE. 78 of the 92 materials that replaced an existing material came from tier restructures. A tier band changes what a customer pays, not what they buy -- which makes it a price break, not an identity. If Claris agrees, those 78 materials never needed to be minted, hierarchied, approved, priced and published.', '78 materials per restructure cycle', 'Product Management', 'Product Management', 'proposed', '2020-01-01', NULL, NULL, NULL),
  ('retail', '2026.10', 'package_format', 4, 'Package format', 'string', 'UNKNOWN', 'PROPOSED', TRUE, TRUE, TRUE, TRUE, TRUE, '12 materials from repackaging, all replacing an existing one. Perpetual and subscription are different fulfilment and different contracts, so this proliferation looks legitimate.', NULL, 'Product Management', 'Product Management', 'proposed', '2020-01-01', NULL, NULL, NULL),
  ('retail', '2026.10', 'currency', 5, 'Currency', 'string', 'UNKNOWN', 'PROPOSED', TRUE, FALSE, TRUE, FALSE, FALSE, 'Currency is derived from region, never chosen independently. Making it identity-bearing would multiply every region by its currency for no business gain.', NULL, 'Finance', 'Finance', 'proposed', '2020-01-01', NULL, NULL, NULL),
  ('retail', '2026.10', 'slp_code', 6, 'SLP', 'string', 'UNKNOWN', 'UNPROPOSED', TRUE, NULL, NULL, NULL, NULL, 'NO PROPOSAL POSSIBLE. No definition of SLP exists anywhere in the process documentation. It is assigned at S3 beside the hierarchy path, eleven steps before pricing, which suggests a classification code rather than a price -- but that is an inference from position, not knowledge.', NULL, 'UNKNOWN', 'UNKNOWN -- identifying the owner is itself the ask', 'undefined', '2020-01-01', NULL, NULL, NULL),
  ('retail', '2026.10', 'description', 7, 'Description', 'string', 'FALSE', 'CONFIRMED', FALSE, FALSE, FALSE, FALSE, FALSE, 'Metadata. Correcting a typo must never mint a SKU.', NULL, 'Marketing', 'Marketing', 'confirmed', '2020-01-01', NULL, NULL, NULL);
