INSERT INTO claris.retail_ontology.identity_rules (domain, ontology_version, rule, ordinal, change_type, reads_dimension, condition_expression, proposed_effect, observed_materials, rationale, owner, status, confirmed_by, confirmed_on) VALUES
  ('retail', '2026.10', 'IR-001', 0, 'new_product_family', NULL, 'always', 'CREATE_PRODUCT', 9, 'A new family is a new commercial product by definition.', 'Product Management', 'proposed', NULL, NULL),
  ('retail', '2026.10', 'IR-002', 1, 'geo_add', 'geo', 'geo.identity_affecting', 'CREATE_CONFIGURATION', 63, 'Legitimate catalogue growth; none of the 63 replaced anything.', 'Product Management', 'proposed', NULL, NULL),
  ('retail', '2026.10', 'IR-003', 2, 'term_add', 'term', 'term.identity_affecting', 'CREATE_CONFIGURATION', 33, 'Different commitment, different contract.', 'Product Management', 'proposed', NULL, NULL),
  ('retail', '2026.10', 'IR-004', 3, 'segment_add', 'segment', 'segment.identity_affecting', 'CREATE_CONFIGURATION', 19, 'Entitlement differs, not only price.', 'Product Management + Finance', 'proposed', NULL, NULL),
  ('retail', '2026.10', 'IR-005', 4, 'tier_restructure', 'user_tier', 'user_tier.identity_affecting', 'NEW_VERSION', 78, 'THE DECISION WORTH MONEY. Proposed as an update, which would have avoided 78 of the 92 mutative materials in the corpus. If Claris says user tier IS identity-bearing, this becomes CREATE_CONFIGURATION and the proliferation is unavoidable.', 'Product Management', 'proposed', NULL, NULL),
  ('retail', '2026.10', 'IR-006', 5, 'repackage', 'package_format', 'package_format.identity_affecting', 'CREATE_CONFIGURATION', 12, 'Different fulfilment; the 12 replacements look legitimate.', 'Product Management', 'proposed', NULL, NULL),
  ('retail', '2026.10', 'IR-007', 6, 'reclassify', 'slp_code', 'hierarchy_path changed', 'NEW_VERSION', 2, 'Reclassification changes where a product sits, not what it is. Today it mints; proposed as an amendment.', 'IS&T', 'proposed', NULL, NULL),
  ('retail', '2026.10', 'IR-008', 7, 'price_change', NULL, 'always', 'NEW_VERSION', 0, 'Confirmed by the corpus: three price changes minted nothing.', 'Finance', 'proposed', NULL, NULL),
  ('retail', '2026.10', 'IR-009', 8, 'rename', 'description', 'always', 'NO_BUSINESS_CHANGE', 0, 'Confirmed by the corpus: two renames minted nothing.', 'Marketing', 'confirmed', NULL, NULL);
INSERT INTO claris.retail_ontology.projection_rules (domain, ontology_version, rule, ordinal, source_object, target_system, proposed_action, requires_new_target_identity, rationale, owner, status, confirmed_by, confirmed_on) VALUES
  ('retail', '2026.10', 'PR-001', 0, 'configuration', 'all_skus', 'CREATE', TRUE, 'Today every change mints a new row. Which change classes may update in place is the question that decides whether an UPDATE_EXISTING conclusion actually avoids a legacy row.', 'Ops', 'confirm_with_claris', NULL, NULL),
  ('retail', '2026.10', 'PR-002', 1, 'configuration', 'sap', 'CREATE', TRUE, 'Material master identity is assumed immutable; confirm.', 'IS&T', 'confirm_with_claris', NULL, NULL),
  ('retail', '2026.10', 'PR-003', 2, 'price', 'ww_pricing', 'UPDATE', FALSE, 'Price rows are versioned in place today.', 'Finance', 'proposed', NULL, NULL),
  ('retail', '2026.10', 'PR-004', 3, 'configuration', 'salesforce', 'CREATE', FALSE, 'Pricebook entries follow the material.', 'IS&T', 'proposed', NULL, NULL);
