INSERT INTO claris.retail_ontology.phases (domain, ontology_version, phase, name, delivers, changes_source_systems, note) VALUES
  ('retail', '2026.10', 1, 'Common Product & Decision Platform', 'Common Decision Workbench, Canonical Product and Configuration model, SKU proliferation control, Legacy projection with reasons, Governance and audit', FALSE, 'Everything the platform does. It reads the legacy systems and writes the canonical model beside them; it does not change how SAP, all_skus or ww_pricing behave.'),
  ('retail', '2026.10', 2, 'Source-System Simplification', 'Eliminate legacy-driven physical identities where feasible', TRUE, 'Uses the evidence phase 1 produces -- specifically every projection carrying LEGACY_SYSTEM_CONSTRAINT or TARGET_SYSTEM_REQUIREMENT -- as the prioritised backlog. Phase 1 measures the cost; phase 2 removes the cause.');
INSERT INTO claris.retail_ontology.use_cases (domain, ontology_version, use_case, ordinal, name, business_question, capability_group, client_outcome, mechanism, decided_by, reads_object_types, result, phase, status, blocked_on, journey_order, in_demo) VALUES
  ('retail', '2026.10', 'UC-01', 0, 'Launch status and missing evidence', 'Where is this configuration version, and what is it waiting on?', 'Common Decision Workbench', 'Accelerate product launch', 'LAUNCH_READINESS', 'Ops', 'configuration_version, evidence, decision', 'Readiness outcome with missing[] named, never an unexplained blank', 1, 'buildable', NULL, NULL, FALSE),
  ('retail', '2026.10', 'UC-02', 1, 'Ownership and ageing', 'Who currently holds it, and since when?', 'Common Decision Workbench', 'Accelerate product launch', 'derived:evidence_to_actor', 'System', 'evidence, actor, decision', 'Named owner, blocked_since, days held', 1, 'buildable', NULL, NULL, FALSE),
  ('retail', '2026.10', 'UC-03', 2, 'Activation authorization', 'May this configuration version be activated?', 'Common Decision Workbench', 'Accelerate product launch', 'LAUNCH_READINESS', 'Ops', 'configuration_version, decision, action', 'Only the two verbs READY entitles become available; a role alone never authorises them', 1, 'buildable', NULL, NULL, FALSE),
  ('retail', '2026.10', 'UC-04', 3, 'Cross-system contradiction', 'Do two systems disagree about the same fact?', 'Common Decision Workbench', 'Accelerate product launch', 'contradiction_checks', 'System', 'evidence', 'MATCH or CONTRADICTED with both conflicting statements retained', 1, 'buildable', NULL, NULL, FALSE),
  ('retail', '2026.10', 'UC-05', 4, 'Rejected versus never answered', 'Was this actually refused, or has nobody responded?', 'Common Decision Workbench', 'Accelerate product launch', 'derived:evidence_state', 'System', 'evidence', 'REJECTED with a reason, or ABSENT with an owner and an age', 1, 'blocked', 'Q-006: whether the workbench may capture approvals. Four required evidence types have no system of record anywhere.', NULL, FALSE),
  ('retail', '2026.10', 'UC-06', 5, 'Launch viability', 'Is this launch still wanted after being blocked?', 'Common Decision Workbench', 'Accelerate product launch', 'LAUNCH_VIABILITY', 'Marketing', 'launch, decision, evidence', 'CONTINUE, ABANDON, or NOT_ASKED -- and NOT_ASKED is the honest default', 1, 'buildable', NULL, NULL, FALSE),
  ('retail', '2026.10', 'UC-20', 6, 'Overall launch readiness', 'Can this version launch, and if not, exactly why?', 'Common Decision Workbench', 'Accelerate product launch', 'LAUNCH_READINESS', 'Ops', 'configuration_version, evidence, decision, projection', 'READY, BLOCKED, AWAITING_APPROVAL, AWAITING_EVIDENCE, CANNOT_DECIDE', 1, 'buildable', NULL, NULL, FALSE),
  ('retail', '2026.10', 'UC-21', 7, 'Portfolio bottleneck', 'Across every launch, where is work actually getting stuck?', 'Common Decision Workbench', 'Accelerate product launch', 'derived:decision_aggregate', 'System', 'decision, evidence, actor, launch', 'Bottlenecks by team, decision, system, reason and duration', 1, 'needs_instances', 'Requires the decision and evidence instance tables. The types are modelled; the runtime rows are not.', NULL, FALSE),
  ('retail', '2026.10', 'UC-07', 8, 'Change classification', 'What kind of change is being requested?', 'SKU Proliferation Control', 'Control SKU proliferation', 'CHANGE_CLASSIFICATION', 'Ops', 'launch, product, configuration, evidence', 'One of nine governed change types, or CANNOT_DECIDE with a reason', 1, 'buildable', NULL, 1, TRUE),
  ('retail', '2026.10', 'UC-17', 9, 'Change impact assessment', 'Before making the change, what will it affect?', 'SKU Proliferation Control', 'Control SKU proliferation', 'derived:change_impact', 'Ops', 'configuration_dimension, configuration_value, projection', 'Dimensions touched, pricing/entitlement/hierarchy impact, systems affected', 1, 'buildable', NULL, 2, FALSE),
  ('retail', '2026.10', 'UC-08', 10, 'Identity assessment', 'Does this require a new product, a new configuration, a new version, or nothing?', 'SKU Proliferation Control', 'Control SKU proliferation', 'IDENTITY_ASSESSMENT', 'Ops', 'product, configuration, configuration_version, configuration_dimension, configuration_value, evidence', 'One of six identity outcomes, with the rule that produced it', 1, 'blocked', 'Q-002: which dimensions are identity-bearing. Seven of eight are unconfirmed, so today this returns CANNOT_DECIDE with the dimension named -- which is the capability working, not failing.', 3, TRUE),
  ('retail', '2026.10', 'UC-18', 11, 'Duplicate configuration prevention', 'Does the requested sellable configuration already exist?', 'SKU Proliferation Control', 'Control SKU proliferation', 'IDENTITY_ASSESSMENT', 'Ops', 'configuration, configuration_version, configuration_value', 'USE_EXISTING with the existing identity returned, or permission to create', 1, 'blocked', 'Q-002. The lookup needs a confirmed identity key; until then it can report candidates but not conclude.', 4, TRUE),
  ('retail', '2026.10', 'UC-19', 12, 'Projection preview', 'Before approval, how many physical records will this create, and where?', 'SKU Proliferation Control', 'Control SKU proliferation', 'projection_matrix', 'Ops', 'configuration_version, projection', 'Predicted record count per target system, each with its reason code', 1, 'buildable', NULL, 5, TRUE),
  ('retail', '2026.10', 'UC-09', 13, 'Legacy projection requirement', 'Which systems require another physical record, and why?', 'SKU Proliferation Control', 'Control SKU proliferation', 'projection_matrix', 'IS&T', 'projection, configuration_version', 'Projection action and projection_reason per target system', 1, 'buildable', NULL, 6, TRUE),
  ('retail', '2026.10', 'UC-10', 14, 'Proliferation measurement', 'How many canonical changes produced how many physical identities?', 'SKU Proliferation Control', 'Control SKU proliferation', 'derived:proliferation_ratio', 'System', 'configuration_version, projection', 'Canonical-to-legacy ratio, split by reason', 1, 'buildable', NULL, 7, TRUE),
  ('retail', '2026.10', 'UC-11', 15, 'Identity-rule simulation', 'What would proliferation look like if user_tier were not identity-bearing?', 'SKU Proliferation Control', 'Control SKU proliferation', 'derived:counterfactual', 'Ops', 'configuration_dimension, configuration_version, projection', 'Avoidable materials and projected reduction, per dimension', 1, 'buildable', NULL, NULL, FALSE),
  ('retail', '2026.10', 'UC-22', 16, 'Legacy dependency analysis', 'Which proliferation is business-required, and which is imposed by legacy architecture?', 'SKU Proliferation Control', 'Control SKU proliferation', 'derived:proliferation_ratio', 'System', 'projection', 'Modernisation candidates ranked by physical records attributable to each source system -- this output IS the phase 2 backlog', 1, 'buildable', NULL, NULL, FALSE),
  ('retail', '2026.10', 'UC-12', 17, 'Governance blocker', 'What prevents an identity decision, and who owes the answer?', 'SKU Proliferation Control', 'Control SKU proliferation', 'open_decisions', 'System', 'configuration_dimension, decision', 'Missing policy, named authority, and what it blocks', 1, 'buildable', NULL, NULL, FALSE),
  ('retail', '2026.10', 'UC-13', 18, 'Decision replay', 'Why did the platform reach this conclusion?', 'Governance, Auditability & Control', 'Make decisions governed and auditable', 'derived:replay', 'System', 'decision, evidence', 'input_digest, policy_version and the exact evidence read, reproducible', 1, 'needs_instances', 'Requires decision instances.', NULL, FALSE),
  ('retail', '2026.10', 'UC-14', 19, 'Separation of duties', 'Did the same actor approve and then execute a controlled action?', 'Governance, Auditability & Control', 'Make decisions governed and auditable', 'derived:sod_check', 'System', 'actor, decision, action', 'SoD violation, or positive evidence of separation', 1, 'blocked', 'Q-004: the separation-of-duties rules between Ops, IS&T and Finance. The traversal works; the policy does not exist.', NULL, FALSE),
  ('retail', '2026.10', 'UC-15', 20, 'Open governance decisions', 'What business-policy questions are still awaiting Claris?', 'Governance, Auditability & Control', 'Make decisions governed and auditable', 'open_decisions', 'System', 'configuration_dimension', 'Owner, question, what it blocks, and what it costs to leave open', 1, 'buildable', NULL, NULL, FALSE),
  ('retail', '2026.10', 'UC-16', 21, 'Ontology and policy drift', 'Does the deployed model still match the approved source definition?', 'Governance, Auditability & Control', 'Make decisions governed and auditable', 'derived:drift_check', 'System', '', 'Match, or a named difference between source_sha256 and the catalogue', 1, 'buildable', NULL, NULL, FALSE);
