  ('retail', '2026.10', 'PM-005', 4, 'CREATE_CONFIGURATION', 'all_skus', 'sku_row', 'CREATE', TRUE, 'CONFIGURATION_REQUIRED', FALSE, 'Ops', 'confirm_with_claris', 'A new sellable configuration. The record represents something that did not exist before.'),
  ('retail', '2026.10', 'PM-006', 5, 'CREATE_CONFIGURATION', 'sap', 'material_master', 'CREATE', TRUE, 'CONFIGURATION_REQUIRED', FALSE, 'IS&T', 'confirm_with_claris', 'A new sellable configuration. The record represents something that did not exist before.'),
  ('retail', '2026.10', 'PM-007', 6, 'CREATE_CONFIGURATION', 'ww_pricing', 'price_row', 'CREATE', TRUE, 'CONFIGURATION_REQUIRED', FALSE, 'Finance', 'proposed', 'A new sellable configuration. The record represents something that did not exist before.'),
  ('retail', '2026.10', 'PM-008', 7, 'CREATE_CONFIGURATION', 'salesforce', 'pricebook_entry', 'CREATE', TRUE, 'CONFIGURATION_REQUIRED', FALSE, 'IS&T', 'proposed', 'A new sellable configuration. The record represents something that did not exist before.'),
  ('retail', '2026.10', 'PM-009', 8, 'NEW_VERSION', 'all_skus', 'sku_row', 'CREATE', TRUE, 'LEGACY_SYSTEM_CONSTRAINT', TRUE, 'Ops', 'confirm_with_claris', 'Canonically this is a new version of something that already exists. The row exists because this system cannot version in place -- which makes it a phase 2 candidate, not catalogue growth.'),
  ('retail', '2026.10', 'PM-010', 9, 'NEW_VERSION', 'sap', 'material_master', 'CREATE', TRUE, 'TARGET_SYSTEM_REQUIREMENT', TRUE, 'IS&T', 'confirm_with_claris', 'The target system\'s own model demands a distinct record even for an unchanged identity. SAP material master identity is treated as immutable; confirm whether that is policy or habit.'),
