  ('retail', '2026.10', 'PM-012', 11, 'NEW_VERSION', 'salesforce', 'pricebook_entry', 'CREATE', TRUE, 'LEGACY_SYSTEM_CONSTRAINT', TRUE, 'IS&T', 'proposed', 'Canonically this is a new version of something that already exists. The row exists because this system cannot version in place -- which makes it a phase 2 candidate, not catalogue growth.'),
  ('retail', '2026.10', 'PM-013', 12, 'USE_EXISTING', 'all_skus', 'sku_row', 'NO_ACTION', FALSE, NULL, FALSE, 'Ops', 'proposed', 'No canonical change, so no target system needs anything. Any row created here today is pure waste and should be measurable as such.'),
